class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        n, res = len(nums), []
        for i in range(n - 2):
            if nums[i] > 0:
                break                   # 最小的都大于 0，后面不可能了
            if i > 0 and nums[i] == nums[i - 1]:
                continue                # 第一个数去重
            l, r = i + 1, n - 1
            while l < r:
                s = nums[i] + nums[l] + nums[r]
                if s < 0:
                    l += 1
                elif s > 0:
                    r -= 1
                else:
                    res.append([nums[i], nums[l], nums[r]])
                    l += 1
                    r -= 1
                    while l < r and nums[l] == nums[l - 1]:
                        l += 1          # 第二个数去重
                    while l < r and nums[r] == nums[r + 1]:
                        r -= 1          # 第三个数去重
        return res

class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        res = set()
        for i, x in enumerate(nums):
            if i and x == nums[i - 1]:
                continue
            seen = set()
            for y in nums[i + 1:]:
                if -x - y in seen:
                    res.add((x, -x - y, y))
                seen.add(y)
        return sorted(map(list, res))

